#!/usr/bin/env python3
"""Rasterises the start-up screen's fallback font (Noto Sans Regular, SIL OFL 1.1) into src/ug2/font_atlas.h.

make_atlas.py <NotoSans-Regular.ttf> <out.h>   (needs Pillow)
"""
import sys
from PIL import Image, ImageDraw, ImageFont

SIZES = [('Small', 16), ('Normal', 19), ('Large', 28)]
FIRST, LAST = 32, 126


def main():
    regular, out = sys.argv[1:3]
    lines = ['#ifndef UG2_FONT_ATLAS_H_', '#define UG2_FONT_ATLAS_H_', '',
             '// Generated by tools/fonts/make_atlas.py from Noto Sans (SIL OFL 1.1, src/ug2/fonts/OFL.txt): U+0020..U+007E',
             '// at three sizes, 4-bit alpha, two pixels a byte with the left one in the high nibble.', '',
             '#include <cstdint>', '', 'namespace ug2 { namespace atlas {', '',
             'struct GlyphData', '{', '    uint32_t offset;    // into Alpha', '    uint8_t width, height;',
             '    int8_t left, top;   // from the pen; top is above the baseline', '    uint16_t advance64;', '};', '',
             'struct SizeData', '{', '    int pixels, ascent, descent;', '    GlyphData glyphs[%d];' % (LAST - FIRST + 1), '};', '']
    blob = bytearray()
    sizes = []
    for name, px in SIZES:
        font = ImageFont.truetype(regular, px)
        ascent, descent = font.getmetrics()
        glyphs = []
        for code in range(FIRST, LAST + 1):
            ch = chr(code)
            x0, y0, x1, y1 = font.getbbox(ch)
            w, h = max(0, x1 - x0), max(0, y1 - y0)
            advance64 = int(round(font.getlength(ch) * 64))
            offset = len(blob)
            if w and h:
                img = Image.new('L', (w, h), 0)
                ImageDraw.Draw(img).text((-x0, -y0), ch, font=font, fill=255)
                px_ = img.load()
                for y in range(h):
                    row = [px_[x, y] >> 4 for x in range(w)]
                    if len(row) % 2:
                        row.append(0)
                    for i in range(0, len(row), 2):
                        blob.append((row[i] << 4) | row[i + 1])
            glyphs.append((offset, w, h, x0, ascent - y0, advance64))
        sizes.append((name, px, ascent, descent, glyphs))
    lines.append('const uint8_t Alpha[%d] =' % len(blob))
    lines.append('{')
    for i in range(0, len(blob), 32):
        lines.append('    ' + ','.join('0x%02x' % b for b in blob[i:i + 32]) + ',')
    lines.append('};')
    lines.append('')
    lines.append('const SizeData Sizes[%d] =' % len(sizes))
    lines.append('{')
    for name, px, ascent, descent, glyphs in sizes:
        lines.append('    { %d, %d, %d, {  // %s' % (px, ascent, descent, name))
        for i in range(0, len(glyphs), 4):
            lines.append('        ' + ' '.join('{ %d, %d, %d, %d, %d, %d },' % g for g in glyphs[i:i + 4]))
        lines.append('    } },')
    lines.append('};')
    lines += ['', '}}', '', '#endif', '']
    with open(out, 'w', newline='\n') as f:
        f.write('\n'.join(lines))


if __name__ == '__main__':
    main()
